mapper.select:
SELECT * FROM C##MULTICOTIZADOR.RESULTADO_COTIZACION
WHERE V_NOMBRE_SEGURO = #{nombreSeguro}
  AND I_COTIZACION_CLAVE = #{cotizacionClave}

SELECT *
FROM C##MULTICOTIZADOR.RESULTADO_COTIZACION
WHERE 1 = 1


    AND I_COTIZACION_CLAVE = #{cotizacionClave}


AND V_NOMBRE_COBERTURA NOT IN ('Completado', 'Error')


    AND V_NOMBRE_SEGURO = #{vNombreSeguro}



    AND V_NOMBRE_COBERTURA = #{vNombreCobertura}

SELECT * FROM (
-- Primera parte: registros que no son 'Error'
SELECT *, 0 as orden
FROM C##MULTICOTIZADOR.RESULTADO_COTIZACION
WHERE 1 = 1

    AND I_COTIZACION_CLAVE = #{cotizacionClave}

AND V_NOMBRE_COBERTURA NOT IN ('Completado', 'Error')

    AND V_NOMBRE_SEGURO = #{vNombreSeguro}


    AND V_NOMBRE_COBERTURA = #{vNombreCobertura}


UNION ALL

-- Segunda parte: solo registros 'Error'
SELECT *, 1 as orden
FROM C##MULTICOTIZADOR.RESULTADO_COTIZACION
WHERE 1 = 1

    AND I_COTIZACION_CLAVE = #{cotizacionClave}

AND V_NOMBRE_COBERTURA = 'Error'

    AND V_NOMBRE_SEGURO = #{vNombreSeguro}


    AND V_NOMBRE_COBERTURA = #{vNombreCobertura}

)
ORDER BY orden, V_NOMBRE_COBERTURA

mapper.delete:
DELETE FROM C##MULTICOTIZADOR.RESULTADO_COTIZACION
WHERE I_RUTINA_CARGA_CLAVE = #{rutinaCargaClave}
  AND V_NOMBRE_COBERTURA = 'Completado'
